game.onUpdateInterval(1000, function () {
    if (chara_hell_mode) {
        sidebone = sprites.create(assets.image`sidebone`, SpriteKind.Projectile)
        if (Math.percentChance(50)) {
            sidebone.x = minX - 5
            sidebone.y = randint(minY, maxY)
            sidebone.vx = 80
        } else {
            sidebone.x = maxX + 5
            sidebone.y = randint(minY, maxY)
            sidebone.vx = -80
        }
        sidebone.setFlag(SpriteFlag.AutoDestroy, true)
    }
})
game.onUpdateInterval(800, function () {
    if (chara) {
        if (moveLeft) {
            sans_battle_idle.vx = -15
        } else {
            sans_battle_idle.vx = 15
        }
        moveLeft = !(moveLeft)
        if (chara_hell_mode) {
            if (moveLeft) {
                sans_battle_idle.vx = -15
            } else {
                sans_battle_idle.vx = 15
            }
            moveLeft = !(moveLeft)
        }
    }
})
// Projectile Engine: Periodically shoots down tracking bones
game.onUpdateInterval(400, function () {
    if (chara) {
        // Spawns a standard 3x8 raw pixel projectile asset dynamically
        bone = sprites.create(assets.image`bone`, SpriteKind.Projectile)
        // Spawn bone within the exact horizontal boundary limits of the battle box
        bone.setPosition(randint(minX - 2, maxX + 2), minY - 5)
        bone.setVelocity(0, 95)
        bone.setFlag(SpriteFlag.AutoDestroy, true)
    }
})
